          {
            "label": "Monomyth",
            "url": "https://en.wikipedia.org/wiki/Hero%27s_journey"
          },
          {
            "label": "Collective Unconscious",
            "url": "https://en.wikipedia.org/wiki/Collective_unconscious"
          }
